-- Run only through Install_148.ps1 against the local Docker Supabase database.
begin;
create extension if not exists pgcrypto;
set local search_path=public,extensions;
create or replace function pg_temp.seed117(t text,d jsonb) returns void language plpgsql as $fn$
declare cols text; sels text; missing text;
begin
 select string_agg(k,',') into missing from jsonb_object_keys(d) k where not exists(select 1 from information_schema.columns c where c.table_schema='public' and c.table_name=t and c.column_name=k);
 if missing is not null then raise exception 'Schema mismatch on %: %',t,missing; end if;
 select string_agg(format('%I',k),',' order by k),string_agg(format('r.%I',k),',' order by k) into cols,sels from jsonb_object_keys(d) k;
 execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I,$1) r on conflict do nothing',t,cols,sels,t) using d;
end $fn$;
do $seed$
