 insert into public.student_period_results(institution_id,student_id,academic_period_id,attempted_credits,earned_credits,total_quality_points,gpa,cgpa,status)
 select 'bf51a84f-2745-5986-99df-96e34b584049',student_id,academic_period_id,attempted,earned,quality,round(quality/attempted,3),round(sum(quality) over(partition by student_id order by start_date,period_number)/sum(attempted) over(partition by student_id order by start_date,period_number),3),'published' from (
 select cr.student_id,ap.id academic_period_id,ap.start_date,ap.period_number,sum(c.credit_hours) attempted,sum(case when cr.passed then c.credit_hours else 0 end) earned,sum(c.credit_hours*cr.grade_point) quality
 from public.course_results cr join public.course_offerings co on co.id=cr.course_offering_id join public.courses c on c.id=co.course_id join public.academic_periods ap on ap.id=co.academic_period_id where cr.institution_id='bf51a84f-2745-5986-99df-96e34b584049' and cr.result_status='published' group by cr.student_id,ap.id,ap.start_date,ap.period_number) z on conflict(student_id,academic_period_id) do nothing;

